import argparse;import json;import sys;import time;from pathlib import Path;sys.path.insert(0,str(Path(__file__).resolve().parent));import client_common;import research_state as rs;from fintrust_gate import ensure_activated;g='## Local rules\nWrite raw_writer.md in English: # <short name> (<ticker>) research note, ## Key takeaways (### Snapshot / ### Highlights / ### Risks / ### Catalysts), ## In-depth analysis, then ## Fundamentals (### Revenue mix), ## Valuation (### Relative strength, ### Peer comparison), ## Industry, ## Risk signals, ## Institutional flows, ## Events and catalysts. End each factual paragraph with (Source: ...). Write host_revenue_mix.json and host_peer_radar.json under charts_dir.\n'
